#!/bin/bash
# AI DISCLAIMER: All of the text in this file was generated by AI.
# G019 per-commit chain, run on the control box. After the 5600G's arm builds: a stock source node on box3900x; the
# replay runs (arms A S SP K F3 X, 2 rounds, reversed in round 2), then the fastbox heavy and small-tx windows (arms
# A Cp CpTW M4 F2 F3, 3 rounds). One snapshot on the 5600G at a time. Marker PC_CHAIN_DONE <ok|FAIL>.
set -u
G=$CTRL/pc; L=$G/pc_chain.log
HIP=${HIP:?the 3900X LAN address}; EXPECT=020744aa54024f2d0c03c68515d98a2060bf01f33e207291c17d733dd5f91c60
P=$HOME/work/pc; BW=$HOME/work/bppall; W=$HOME/work/fastbox; SN=$HOME/work/research-artifacts/snapshots
log() { echo "$(date -u +%FT%TZ) $*" >> $L; }
stopsrc() { ssh -n box3900x "bash ~/work/g016/src_node.sh $HIP stop" >> $L 2>&1; }
fail() { log "$*"; stopsrc; log "PC_CHAIN_DONE FAIL"; exit 1; }
log "chain start"
until ssh -n box5600g "grep -q PC_BUILD_DONE $P/build.log"; do sleep 60; done
ssh -n box5600g "grep -q 'PC_BUILD_DONE ok' $P/build.log" || { log "builds failed"; log "PC_CHAIN_DONE FAIL"; exit 1; }
for a in A S SP K Cp CpTW M4 F2 F3 X; do ssh -n box5600g "test -x $P/bin/$a/monerod" || { log "no binary for $a"; log "PC_CHAIN_DONE FAIL"; exit 1; }; done
log "builds: $(ssh -n box5600g "grep -E '^[A-Za-z0-9]+: ' $P/build.log | cut -c1-90 | tr '\n' ';'")"
ssh -n box3900x "pgrep -u $USER -x monerod" > /dev/null && { log "a monerod runs on box3900x"; log "PC_CHAIN_DONE FAIL"; exit 1; }
ssh -n box5600g "pgrep -u $USER -x monerod" > /dev/null && { log "a monerod runs on the 5600G"; log "PC_CHAIN_DONE FAIL"; exit 1; }
ssh -n box3900x "RPC_LAN=1 bash ~/work/g016/src_node.sh $HIP start" >> $L 2>&1 || fail "source node did not start"
~/snapshots/snapctl.sh put box5600g stressnet_h3103300c box3900x >> $L 2>&1 || fail "put stressnet_h3103300c"
log "replay snapshot on the 5600G; free $(ssh -n box5600g "df --output=avail -BG ~ | tail -1")"
rep() {  # <name> <arm>
  local name=$1 arm=$2
  log "start $name"
  ssh -n box5600g "cd $P && (env SRC=$HIP:28180 EXPECT=$EXPECT setsid nohup bash pc_replay.sh $name $arm > $P/logs/$name.out 2>&1 < /dev/null &)"
  until ssh -n box5600g "grep -q BPP_RUN_DONE $BW/runs/$name/run.log 2>/dev/null || grep -q ABORT $P/logs/$name.out"; do sleep 30; done
  ssh -n box5600g "tail -4 $BW/runs/$name/run.log 2>/dev/null; cat $P/logs/$name.out" >> $L
  ssh -n box5600g "grep -q 'BPP_RUN_DONE end' $BW/runs/$name/run.log && grep -q HASH_OK $BW/runs/$name/run.log" || fail "$name did not end ok"
}
for a in A S SP K F3 X; do rep pcr1_$a $a; done
for a in X F3 K SP S A; do rep pcr2_$a $a; done
ssh -n box5600g "rm -f ~/work/chains/stressnet/testnet/lmdb/data.mdb ~/work/chains/stressnet/testnet/lmdb/lock.mdb"
~/snapshots/snapctl.sh drop box5600g stressnet_h3103300c box3900x >> $L 2>&1 || fail "drop stressnet_h3103300c"
win() {  # <snapshot> <name> <END> <TIMEOUT> <extra>
  local snap=$1 name=$2 end=$3 to=$4 wx="$5"
  ~/snapshots/snapctl.sh put box5600g $snap box3900x >> $L 2>&1 || fail "put $snap"
  log "snapshot $snap on the 5600G; free $(ssh -n box5600g "df --output=avail -BG ~ | tail -1")"
  log "start $name"
  ssh -n box5600g "mkdir -p $P/out && cd $P && (env PEER=$HIP:28180 PEER_RPC=$HIP:28189 DD=$W/run SNAP=$SN/$snap setsid nohup bash fbm_pc_window.sh $P/out/$name $end $to 3 \"$wx\" A Cp CpTW M4 F2 F3 > /dev/null 2>&1 < /dev/null &)"
  until ssh -n box5600g "grep -q FBM_WIN_DONE $P/out/$name.fbm 2>/dev/null"; do sleep 30; done
  ssh -n box5600g "tail -2 $P/out/$name.fbm; tail -3 $P/out/$name/summary.txt" >> $L
  ssh -n box5600g "grep -q 'FBM_WIN_DONE 0' $P/out/$name.fbm && tail -1 $P/out/$name/summary.txt | grep -qx AB_COMPLETE" || fail "$name did not complete"
  ssh -n box5600g "rm -rf $W/run"
  ~/snapshots/snapctl.sh drop box5600g $snap box3900x >> $L 2>&1 || fail "drop $snap"
}
win stressnet_wedge_h3105401 heavy 3105444 2400 "--block-sync-size 5"
win stressnet_h3106400c small 3106800 3000 ""
stopsrc
log "PC_CHAIN_DONE ok"
